impl NativeApp {
    /// Its hosting on the target this shell is built for.
    pub const fn on_this_target(&self) -> Hosting {
        if cfg!(target_arch = "wasm32") {
            self.wasm
        } else if cfg!(target_os = "android") {
            self.android
        } else if cfg!(target_os = "ios") {
            self.ios
        } else if cfg!(target_env = "ohos") {
            self.ohos
        } else if cfg!(target_os = "macos") {
            self.macos
        } else if cfg!(target_os = "windows") {
            self.windows
        } else {
            self.linux
        }
    }
}

impl NativeApp {
    /// The rule for one of its tools, if the manifest sets one.
    pub fn tool(&self, name: &str) -> Option<&'static ToolPolicy> {
        self.tools.iter().find(|rule| rule.tool == name)
    }
}

/// The manifest entry for an app id.
pub fn find(id: &str) -> Option<&'static NativeApp> {
    APPS.iter().find(|app| app.id == id)
}

/// The Cargo package (`crate`) of an app with a `bin`: what a process
/// launch builds from the workspace, `cargo build --locked -p
/// octosense-process-apps -p <package>` (crates/process-apps).
pub fn package_of(id: &str) -> Option<&'static str> {
    match id {
        "reference" => Some("octosense-reference"),
        "sheets" => Some("makepad-sheets"),
        "terminal" => Some("makepad-terminal"),
        "calculator" => Some("makepad-calculator"),
        "clock" => Some("makepad-clock"),
        "notes" => Some("makepad-notes"),
        "reminders" => Some("makepad-reminders"),
        "weather" => Some("makepad-weather"),
        "task" => Some("makepad-task"),
        _ => None,
    }
}

/// Push the native modules this build links, in manifest order.
#[allow(unused_variables)]
pub fn link(out: &mut Vec<&'static dyn AppModule>) {
    #[cfg(feature = "app-rinx")]
    out.push(&rinx::module::RINX_MODULE);
    #[cfg(any(feature = "app-reference", native_mobile))]
    out.push(&octosense_reference::REFERENCE_MODULE);
    #[cfg(feature = "app-octobuddy")]
    out.push(&octosense_octobuddy::OCTOBUDDY_MODULE);
    #[cfg(any(feature = "app-sheets", native_mobile))]
    out.push(&makepad_sheets::SHEETS_MODULE);
    #[cfg(feature = "app-terminal")]
    out.push(&makepad_terminal::TERMINAL_MODULE);
    #[cfg(feature = "app-appcard")]
    out.push(&octosense_appcard::APPCARD_MODULE);
    #[cfg(any(feature = "app-hub", native_mobile))]
    {
        out.push(&octosense_app_hub_app::APP_HUB_MODULE);
        out.push(&octosense_app_hub_app::CARD_MODULE);
    }
    #[cfg(feature = "app-calculator")]
    out.push(&makepad_calculator::CALCULATOR_MODULE);
    #[cfg(feature = "app-clock")]
    out.push(&makepad_clock::CLOCK_MODULE);
    #[cfg(feature = "app-notes")]
    out.push(&makepad_notes::NOTES_MODULE);
    #[cfg(feature = "app-reminders")]
    out.push(&makepad_reminders::REMINDERS_MODULE);
    #[cfg(feature = "app-weather")]
    out.push(&makepad_weather::WEATHER_MODULE);
    #[cfg(feature = "app-octoscode")]
    out.push(&octoscode_module::OCTOSCODE_MODULE);
}
